package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {









    @Test
    public void testIsNumber_Exponent() {
        assertTrue(NumberUtils.isNumber("123e456"));
        assertTrue(NumberUtils.isNumber("123E456"));
        assertTrue(NumberUtils.isNumber("123e+456"));
        assertTrue(NumberUtils.isNumber("123e-456"));
        assertFalse(NumberUtils.isNumber("e123"));
        assertFalse(NumberUtils.isNumber("123e"));
        assertFalse(NumberUtils.isNumber("123e++456"));
        assertFalse(NumberUtils.isNumber("123e1.2")); // Dec in exponent not allowed
        assertFalse(NumberUtils.isNumber("123e12E3"));
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        assertTrue(NumberUtils.isNumber("123.45f"));

        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));
        assertTrue(NumberUtils.isNumber("123.45L"));

        // L with exponent is not allowed per code: return foundDigit && !hasExp;
        assertFalse(NumberUtils.isNumber("123e10L"));

        // Invalid qualifiers
        assertFalse(NumberUtils.isNumber("123g"));
        assertFalse(NumberUtils.isNumber("123.45e10f")); // cannot have qualifier after E? 
        // Actually, the logic checks the last char. If last char is 'f', it checks !allowSigns.
        // If it's "123e10f", the loop processes 'e', '1', '0'. Then i points to 'f'.
        // 'f' is a valid qualifier.
        assertTrue(NumberUtils.isNumber("123e10f")); 
    }




}

